function RankCard({xp}:{xp:number}) {
 const rank=getRank(xp);
 return <section className="rank-card" aria-label="Fitness rank progression">
  <div className="rank-emblem" style={{"--rank-color":rank.color} as React.CSSProperties}><ShieldCheck size={28}/></div>
  <div className="rank-copy"><div className="eyebrow">YOUR FITNESS RANK</div><h2 style={{color:rank.color}}>{rank.rank}</h2><p>{rank.label} · {xp.toLocaleString()} XP earned</p>
   <div className="rank-progress"><span style={{width:rank.progress+"%",background:rank.color}}/></div>
   <small>{rank.nextRank ? rank.xpToNext.toLocaleString()+" XP to "+rank.nextRank : "Highest rank reached — keep setting your own records"}</small>
  </div><div className="rank-level"><strong>{rank.progress}%</strong><span>TO NEXT</span></div>
 </section>;
}
function Heading({eyebrow,title,description,action}:{eyebrow:string;title:React.ReactNode;description:string;action?:React.ReactNode}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div>{action}</div>;}
function Overview(p:{protein:number;calories:number;calorieGoal:number;proteinGoal:number;water:number;spent:number;logs:Log[];setTab:(t:Tab)=>void;pct:(v:number,t:number)=>number;xp:number;workoutStreak:number;workoutsThisWeek:number;consistencyLoading:boolean}){
 return <><Heading eyebrow={todayLabel()} title={<>Build your <em>momentum.</em></>} description="A little progress, repeated often, adds up." action={<button className="primary-btn" onClick={()=>p.setTab("Training")}><Plus size={16}/> Log activity</button>}/><RankCard xp={p.xp}/><div className="hero-grid"><div className="hero-card"><div className="hero-top"><span className="pill"><span className="live-dot"/> TODAY&apos;S FOCUS</span><span className="hero-date">PERSONAL PLAN</span></div><div className="hero-main"><div><div className="hero-kicker">YOUR TRAINING WORKSPACE</div><h2>Build a session</h2><p>Choose exercises, sets, reps and load</p></div><div className="hero-graphic"><div className="orb orb-one"/><div className="orb orb-two"/><Dumbbell size={58}/></div></div><div className="hero-bottom"><div><Clock3 size={15}/> Custom exercises <span>·</span> saved history</div><button className="hero-link" onClick={()=>p.setTab("Training")}>View session <ArrowRight size={15}/></button></div></div><div className="streak-card"><div className="streak-icon"><Flame size={19}/></div><div className="eyebrow">YOUR CONSISTENCY</div><div className="streak-number">{p.consistencyLoading?"—":p.workoutsThisWeek}<small> / 7 days</small></div><p>{p.consistencyLoading?"Checking your saved workout history…":p.workoutsThisWeek===0?"Save a workout to start your weekly record.":"Days with at least one saved workout this week."}</p><div className="streak-bars" aria-label={p.consistencyLoading?"Loading workout days":`${p.workoutsThisWeek} of 7 days with a workout`}>{Array.from({length:7},(_,i)=><span key={i} className={!p.consistencyLoading&&i<p.workoutsThisWeek?"filled":""}/>)}</div><div className="streak-foot"><span>ACTIVE STREAK</span><b>{p.consistencyLoading?"—":`${p.workoutStreak} ${p.workoutStreak===1?"day":"days"}`}</b></div></div></div>
 <div className="section-heading"><div><div className="eyebrow">DAILY SNAPSHOT</div><h3>How you&apos;re tracking</h3></div><span className="subtle-label">TODAY SO FAR</span></div><div className="stats-grid"><Stat label="Energy intake" value={p.calories.toLocaleString()} unit="kcal" pct={p.calorieGoal>0?p.pct(p.calories,p.calorieGoal):0} foot={p.calorieGoal>0?`of ${p.calorieGoal.toLocaleString()} kcal goal`:"set a daily target to track intake"} icon={<Flame size={16}/>} tone="orange"/><Stat label="Protein" value={String(Math.round(p.protein))} unit="g" pct={p.proteinGoal>0?p.pct(p.protein,p.proteinGoal):0} foot={p.proteinGoal>0?`of ${p.proteinGoal} g goal`:"set a daily target to track protein"} icon={<Zap size={16}/>} tone="green"/><Stat label="Water" value={String(p.water)} unit="glasses" pct={0} foot="glasses logged today · target optional" icon={<Activity size={16}/>} tone="blue"/><Stat label="Food spending" value={money(p.spent)} unit="spent today" pct={0} foot="from your saved budget entries" icon={<Wallet size={16}/>} tone="violet"/></div>
 <div className="lower-grid"><div className="panel-card"><div className="panel-head"><div><div className="eyebrow">QUICK ACTIONS</div><h3>Keep it moving</h3></div><Sparkles size={17} className="muted"/></div><div className="quick-actions"><Quick icon={<Dumbbell size={18}/>} title="Log a workout" sub="Record sets & reps" onClick={()=>p.setTab("Training")}/><Quick icon={<Utensils size={18}/>} title="Add a meal" sub="Track food & macros" onClick={()=>p.setTab("Nutrition")}/><Quick icon={<Wallet size={18}/>} title="Check allowance" sub="See your food budget" onClick={()=>p.setTab("Budget")}/></div></div><div className="panel-card"><div className="panel-head"><div><div className="eyebrow">RECENT ACTIVITY</div><h3>Your daily log</h3></div><span className="subtle-label">{p.logs.length} ENTRIES</span></div>{p.logs.length===0?<div className="empty-state"><div className="empty-icon"><Activity size={20}/></div><b>Your story starts here</b><span>Log a meal, workout or water to see it here.</span></div>:<div className="activity-list">{p.logs.slice(0,4).map(l=><div className="activity-row" key={l.id}><span className="activity-mark"><Check size={14}/></span><span><b>{l.label}</b><small>{l.time}</small></span><strong>{l.amount} {l.unit}</strong></div>)}</div>}</div></div></>;
}
