function Training({addLog}:{addLog:(l:string,a:number,u:string)=>void}){
 const [exercises,setExercises]=useState<TrainingExercise[]>([]);
 const [sessionTitle,setSessionTitle]=useState("My workout");
 const [sessionId,setSessionId]=useState<string|null>(null);
 const [done,setDone]=useState<string[]>([]);
 const [saving,setSaving]=useState<string|null>(null);
 const [message,setMessage]=useState("");
 const [history,setHistory]=useState<{id:string;title:string|null;started_at:string;sets:{id:string;exercise_name:string;set_number:number;reps:number;weight_kg:number|null}[]}[]>([]);
 const [historyLoading,setHistoryLoading]=useState(true);
 const [search,setSearch]=useState("");
 const [muscleFilter,setMuscleFilter]=useState("All");
 const [showLibrary,setShowLibrary]=useState(false);
 const [customName,setCustomName]=useState("");
 const [customMuscle,setCustomMuscle]=useState("Chest");
 const [goal,setGoal]=useState("Build muscle");
 const [level,setLevel]=useState("Beginner");
 const [equipment,setEquipment]=useState<string[]>(["Dumbbells","Barbell","Machine","Cable","Bodyweight"]);
 const [duration,setDuration]=useState("45");
 const [showPersonalize,setShowPersonalize]=useState(false);
 const [suggesting,setSuggesting]=useState(false);
 const [suggestionSource,setSuggestionSource]=useState("");
 const [templates,setTemplates]=useState<{name:string;exercises:TrainingExercise[]}[]>([]);const [customLibrary,setCustomLibrary]=useState<TrainingExercise[]>([]);
 const [templateName,setTemplateName]=useState("");const [split,setSplit]=useState("Push / Pull / Legs");const [weeklyPlan,setWeeklyPlan]=useState<Record<string,string>>({});const [showPlanner,setShowPlanner]=useState(false);
 const [showTemplates,setShowTemplates]=useState(false);
 const [expanded,setExpanded]=useState<number|null>(0);
 const [historyBusy,setHistoryBusy]=useState<string|null>(null);
 const [editingSet,setEditingSet]=useState<string|null>(null);
 const [editReps,setEditReps]=useState("");
 const [editLoad,setEditLoad]=useState("");
 useEffect(()=>{try{const raw=localStorage.getItem("fitledger-workout-builder");if(raw){const d=JSON.parse(raw);if(Array.isArray(d.exercises))setExercises(d.exercises);if(d.title)setSessionTitle(d.title);if(typeof d.sessionId==="string")setSessionId(d.sessionId);if(Array.isArray(d.done))setDone(d.done);if(d.goal)setGoal(d.goal);if(d.level)setLevel(d.level);if(Array.isArray(d.equipment))setEquipment(d.equipment);if(d.duration)setDuration(d.duration);if(Array.isArray(d.templates))setTemplates(d.templates);if(Array.isArray(d.customLibrary))setCustomLibrary(d.customLibrary);if(d.split)setSplit(d.split);if(d.weeklyPlan&&typeof d.weeklyPlan==="object")setWeeklyPlan(d.weeklyPlan);}}catch(e){console.warn("Workout builder restore failed",e);}},[]);
 useEffect(()=>{localStorage.setItem("fitledger-workout-builder",JSON.stringify({exercises,title:sessionTitle,sessionId,done,goal,level,equipment,duration,templates,customLibrary,split,weeklyPlan}));},[exercises,sessionTitle,sessionId,done,goal,level,equipment,duration,templates,customLibrary,split,weeklyPlan]);
 const loadHistory=async()=>{setHistoryLoading(true);try{const supabase=createClient();const {data:{user}}=await supabase.auth.getUser();if(!user){setHistory([]);return;}const {data:sessions,error}=await supabase.from("workout_sessions").select("id,title,started_at").eq("user_id",user.id).order("started_at",{ascending:false}).limit(10);if(error)throw error;const ids=(sessions||[]).map(x=>x.id);let sets:{id:string;session_id:string;exercise_name:string;set_number:number;reps:number;weight_kg:number|null}[]=[];if(ids.length){const result=await supabase.from("workout_sets").select("id,session_id,exercise_name,set_number,reps,weight_kg").eq("user_id",user.id).in("session_id",ids).order("set_number",{ascending:true});if(result.error)throw result.error;sets=result.data||[];}setHistory((sessions||[]).map(x=>({...x,sets:sets.filter(y=>y.session_id===x.id)})));}catch(e){console.error("Workout history load failed",e);setMessage("Workout history could not load. Please refresh.");}finally{setHistoryLoading(false);}};
 useEffect(()=>{void loadHistory();},[]);
 const updateExercise=(index:number,key:keyof TrainingExercise,value:string)=>setExercises(old=>old.map((x,i)=>i===index?{...x,[key]:value}:x));
 const addExercise=(exercise:TrainingExercise)=>{if(exercises.some(x=>x.name.toLowerCase()===exercise.name.toLowerCase())){setMessage("That exercise is already in this workout.");return;}setExercises(old=>[...old, {...exercise}]);setExpanded(exercises.length);setShowLibrary(false);setSearch("");setMessage(exercise.name+" added to your workout.");};
 const removeExercise=(index:number)=>{setExercises(old=>old.filter((_,i)=>i!==index));setExpanded(null);};
 const saveExercise=async(exercise:TrainingExercise)=>{setMessage("");const count=Number(exercise.sets),reps=Number(exercise.reps),weight=exercise.weight.trim()===""?null:Number(exercise.weight);if(!Number.isInteger(count)||count<1||count>10||!Number.isInteger(reps)||reps<1||reps>1000||(weight!==null&&(!Number.isFinite(weight)||weight<0||weight>1000))){setMessage("Check sets, reps or duration, and load before saving.");return;}setSaving(exercise.name);try{const supabase=createClient();const {data:{user}}=await supabase.auth.getUser();if(!user){setMessage("Please sign in to save a workout.");return;}let activeSession=sessionId;if(!activeSession){const {data,error}=await supabase.from("workout_sessions").insert({user_id:user.id,title:sessionTitle.trim()||"Workout"}).select("id").single();if(error||!data)throw error||new Error("Could not start workout");activeSession=data.id;setSessionId(activeSession);}if(activeSession){const {error:titleError}=await supabase.from("workout_sessions").update({title:sessionTitle.trim()||"Workout"}).eq("id",activeSession).eq("user_id",user.id);if(titleError)throw titleError;}const {data:existing,error:existingError}=await supabase.from("workout_sets").select("set_number").eq("user_id",user.id).eq("session_id",activeSession).eq("exercise_name",exercise.name).order("set_number",{ascending:false}).limit(1);if(existingError)throw existingError;const next=(existing?.[0]?.set_number||0)+1;const now=new Date().toISOString();const rows=Array.from({length:count},(_,i)=>({user_id:user.id,session_id:activeSession,exercise_name:exercise.name,set_number:next+i,reps,weight_kg:exercise.kind==="weighted"?weight:null,completed_at:now}));const {error}=await supabase.from("workout_sets").insert(rows);if(error)throw error;setDone(old=>old.includes(exercise.name)?old:[...old,exercise.name]);addLog(exercise.name,count,"sets");setMessage(exercise.name+" saved to this session.");await loadHistory();}catch(e){console.error("Workout save failed",e);setMessage("Could not save this exercise. Check your connection and try again.");}finally{setSaving(null);}};
 const filtered=[...exerciseLibrary,...customLibrary].filter(x=>(muscleFilter==="All"||x.muscle===muscleFilter)&&x.name.toLowerCase().includes(search.toLowerCase())&&(equipment.includes(x.equipment)||x.equipment==="Bodyweight"||x.equipment==="Custom"));
 const recommend=async()=>{setSuggesting(true);setMessage("");setSuggestionSource("");const profile={goal,level,equipment,duration,availableExercises:exerciseLibrary};try{const response=await fetch("/api/workout-suggestions",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(profile)});if(!response.ok)throw new Error("AI service unavailable");const data=await response.json();if(Array.isArray(data.exercises)&&data.exercises.length){setExercises(data.exercises.map((x:TrainingExercise)=>({...x})));setSessionTitle(data.title||"Personalized workout");setSuggestionSource("AI personalized");setMessage("Your suggested workout is ready. Review it and adjust anything before training.");}}catch{const filteredLibrary=exerciseLibrary.filter(x=>equipment.includes(x.equipment));const byGoal=goal==="Build muscle"?["Chest","Back","Legs","Shoulders","Arms"]:goal==="Get stronger"?["Legs","Chest","Back","Shoulders"]:["Legs","Core","Back","Chest"];const count=Math.max(3,Math.min(7,Math.floor(Number(duration)/8)));const picked=byGoal.flatMap(m=>filteredLibrary.filter(x=>x.muscle===m)).slice(0,count).map(x=>({...x,sets:level==="Beginner"?"2":"3",reps:goal==="Get stronger"?"6":goal==="Improve fitness"?"12":"10"}));setExercises(picked);setSessionTitle(goal==="Build muscle"?"Muscle-building session":goal==="Get stronger"?"Strength session":"Balanced fitness session");setSuggestionSource("Smart suggestions");setMessage("A personalized starter plan is ready using your preferences. Review and adjust before starting.");}finally{setSuggesting(false);}};
 const startEdit=(set:{id:string;reps:number;weight_kg:number|null})=>{setEditingSet(set.id);setEditReps(String(set.reps));setEditLoad(set.weight_kg===null?"":String(set.weight_kg));};
 const saveSet=async()=>{if(!editingSet)return;const reps=Number(editReps),weight=editLoad.trim()===""?null:Number(editLoad);if(!Number.isInteger(reps)||reps<1||reps>1000||(weight!==null&&(!Number.isFinite(weight)||weight<0||weight>1000))){setMessage("Enter valid reps or duration and load.");return;}setHistoryBusy(editingSet);try{const supabase=createClient();const {data:{user}}=await supabase.auth.getUser();if(!user)throw Error("Not signed in");const {error}=await supabase.from("workout_sets").update({reps,weight_kg:weight}).eq("id",editingSet).eq("user_id",user.id);if(error)throw error;setEditingSet(null);await loadHistory();setMessage("Set updated.");}catch(e){console.error(e);setMessage("Could not update set.");}finally{setHistoryBusy(null);}};
 const deleteSet=async(id:string)=>{if(!window.confirm("Delete this set?"))return;setHistoryBusy(id);try{const supabase=createClient();const {data:{user}}=await supabase.auth.getUser();if(!user)throw Error("Not signed in");const {error}=await supabase.from("workout_sets").delete().eq("id",id).eq("user_id",user.id);if(error)throw error;await loadHistory();}catch(e){console.error(e);setMessage("Could not delete set.");}finally{setHistoryBusy(null);}};
 const deleteSession=async(id:string)=>{if(!window.confirm("Delete this workout and all its sets?"))return;setHistoryBusy(id);try{const supabase=createClient();const {data:{user}}=await supabase.auth.getUser();if(!user)throw Error("Not signed in");const delSets=await supabase.from("workout_sets").delete().eq("session_id",id).eq("user_id",user.id);if(delSets.error)throw delSets.error;const delSession=await supabase.from("workout_sessions").delete().eq("id",id).eq("user_id",user.id);if(delSession.error)throw delSession.error;if(sessionId===id){setSessionId(null);setDone([]);}await loadHistory();}catch(e){console.error(e);setMessage("Could not delete workout.");await loadHistory();}finally{setHistoryBusy(null);}};
 const splitOptions:Record<string,{day:string;name:string;muscles:string[]|null}[]>={"Push / Pull / Legs":[{day:"Monday",name:"Push",muscles:["Chest","Shoulders","Arms"]},{day:"Tuesday",name:"Pull",muscles:["Back","Arms"]},{day:"Wednesday",name:"Legs",muscles:["Legs","Glutes","Core"]},{day:"Thursday",name:"Rest",muscles:null},{day:"Friday",name:"Push",muscles:["Chest","Shoulders","Arms"]},{day:"Saturday",name:"Pull",muscles:["Back","Arms"]},{day:"Sunday",name:"Rest",muscles:null}],"Upper / Lower":[{day:"Monday",name:"Upper",muscles:["Chest","Back","Shoulders","Arms"]},{day:"Tuesday",name:"Lower",muscles:["Legs","Glutes","Core"]},{day:"Wednesday",name:"Rest",muscles:null},{day:"Thursday",name:"Upper",muscles:["Chest","Back","Shoulders","Arms"]},{day:"Friday",name:"Lower",muscles:["Legs","Glutes","Core"]},{day:"Saturday",name:"Rest",muscles:null},{day:"Sunday",name:"Rest",muscles:null}],"Full Body 3x":[{day:"Monday",name:"Full Body",muscles:["Chest","Back","Legs","Shoulders","Core"]},{day:"Tuesday",name:"Rest",muscles:null},{day:"Wednesday",name:"Full Body",muscles:["Chest","Back","Legs","Shoulders","Core"]},{day:"Thursday",name:"Rest",muscles:null},{day:"Friday",name:"Full Body",muscles:["Chest","Back","Legs","Shoulders","Core"]},{day:"Saturday",name:"Rest",muscles:null},{day:"Sunday",name:"Rest",muscles:null}],"Four-day Upper / Lower":[{day:"Monday",name:"Upper",muscles:["Chest","Back","Shoulders","Arms"]},{day:"Tuesday",name:"Lower",muscles:["Legs","Glutes","Core"]},{day:"Wednesday",name:"Rest",muscles:null},{day:"Thursday",name:"Upper",muscles:["Chest","Back","Shoulders","Arms"]},{day:"Friday",name:"Lower",muscles:["Legs","Glutes","Core"]},{day:"Saturday",name:"Rest",muscles:null},{day:"Sunday",name:"Rest",muscles:null}]};
 const applySplit=()=>{const plan:Record<string,string>={};for(const day of splitOptions[split])plan[day.day]=day.name;setWeeklyPlan(plan);setMessage(split+" weekly schedule applied. You can customize each day.");};
 const loadPlanDay=(day:string)=>{const label=weeklyPlan[day];if(!label||label==="Rest"){setMessage(day+" is a recovery day. No workout loaded.");return;}const config=splitOptions[split].find(x=>x.day===day);const muscles=config?.muscles||[];const picked=exerciseLibrary.filter(x=>muscles.includes(x.muscle)&& (equipment.includes(x.equipment)||x.equipment==="Bodyweight")).slice(0,6).map(x=>({...x}));setExercises(picked);setSessionTitle(day+" · "+label);setSessionId(null);setDone([]);setMessage(day+" "+label+" workout loaded. Review and customize before logging.");setExpanded(0);};
 const muscles=["All","Chest","Back","Shoulders","Arms","Legs","Core","Glutes"];
 return <><Heading eyebrow="TRAINING / WORKOUT BUILDER" title={<>Build a session that <em>fits.</em></>} description="Your plan, your equipment, your pace." action={<span className="pill"><span className="live-dot"/> TRAINING</span>}/>
 <section className="builder-hero"><div><span className="eyebrow">WORKOUT IN PROGRESS</span><input className="builder-title-input" aria-label="Workout name" maxLength={60} value={sessionTitle} onChange={e=>setSessionTitle(e.target.value)} placeholder="Name your workout"/><p>{exercises.length} exercises · {exercises.reduce((n,x)=>n+Number(x.sets||0),0)} planned sets · {done.length} logged</p></div><div className="builder-hero-actions"><button type="button" className="builder-button secondary" onClick={()=>{setExercises([]);setSessionId(null);setDone([]);setSessionTitle("New workout");setMessage("Started a blank workout.");}}>New blank</button><button type="button" className="builder-button" onClick={()=>setShowPersonalize(v=>!v)}><Sparkles size={15}/> Personalize</button></div></section>
 <section className="builder-preferences"><button type="button" className="builder-section-toggle" onClick={()=>setShowPersonalize(v=>!v)}><span><b>Training preferences</b><small>Goal, experience, equipment and session length</small></span><ChevronDown size={18} className={showPersonalize?"rotated":""}/></button>{showPersonalize&&<div className="builder-preference-grid"><label>Primary goal<select value={goal} onChange={e=>setGoal(e.target.value)}><option>Build muscle</option><option>Get stronger</option><option>Improve fitness</option><option>General health</option></select></label><label>Experience<select value={level} onChange={e=>setLevel(e.target.value)}><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select></label><label>Session length<select value={duration} onChange={e=>setDuration(e.target.value)}><option value="20">20 minutes</option><option value="30">30 minutes</option><option value="45">45 minutes</option><option value="60">60 minutes</option><option value="75">75 minutes</option></select></label><div className="builder-equipment"><span>Available equipment</span><div>{["Dumbbells","Barbell","Machine","Cable","Bodyweight"].map(item=><button type="button" key={item} className={equipment.includes(item)?"chosen":""} onClick={()=>setEquipment(old=>old.includes(item)?old.filter(x=>x!==item):[...old,item])}>{item}</button>)}</div></div><button type="button" className="builder-button ai-generate" disabled={suggesting||equipment.length===0} onClick={()=>void recommend()}>{suggesting?<><Activity size={15}/> Building your plan…</>:<><Sparkles size={15}/> Generate my workout</>}</button><p className="builder-note">Suggestions adapt to your selected goal, experience, equipment and time. Review every exercise before logging.</p></div>}</section>
 <section className="builder-panel weekly-planner"><button type="button" className="builder-section-toggle" onClick={()=>setShowPlanner(v=>!v)}><span><b>Weekly routine planner</b><small>Choose a split, assign training and recovery days</small></span><ChevronDown size={18} className={showPlanner?"rotated":""}/></button>{showPlanner&&<div className="weekly-planner-body"><label className="weekly-split-label">Training split<select value={split} onChange={e=>setSplit(e.target.value)}>{Object.keys(splitOptions).map(x=><option key={x}>{x}</option>)}</select></label><button className="builder-button" type="button" onClick={applySplit}>Apply weekly schedule</button><div className="weekly-days">{["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"].map(day=><div className="weekly-day" key={day}><b>{day}</b><select aria-label={day+" routine"} value={weeklyPlan[day]||"Rest"} onChange={e=>setWeeklyPlan(old=>({...old,[day]:e.target.value}))}><option>Rest</option><option>Push</option><option>Pull</option><option>Legs</option><option>Upper</option><option>Lower</option><option>Full Body</option><option>Cardio / Mobility</option></select><button className="builder-button secondary" type="button" disabled={!weeklyPlan[day]||weeklyPlan[day]==="Rest"} onClick={()=>loadPlanDay(day)}>Load</button></div>)}</div><p className="builder-note">Rest days are intentional. Adjust the schedule to your availability and allow recovery between demanding sessions. Schedule is saved on this device.</p></div>}</section>
 <div className="builder-toolbar"><div><span className="eyebrow">YOUR SESSION</span><h3>Exercise plan</h3><small className="builder-note">{sessionId?"Active workout · saved sets stay in this session":"Plan ready · logging an exercise starts a new session"}</small></div><div className="builder-toolbar-actions">{sessionId&&<button className="builder-button secondary" type="button" onClick={()=>{if(!window.confirm("Finish this workout session? Your saved sets will remain in history."))return;setSessionId(null);setDone([]);setMessage("Workout session finished. Your next logged workout will start a new session.");}}>Finish session</button>}<button className="builder-button secondary" type="button" onClick={()=>setShowTemplates(v=>!v)}>My routines</button><button className="builder-button" type="button" onClick={()=>setShowLibrary(v=>!v)}><Plus size={15}/> Add exercise</button></div></div>
 {showTemplates&&<section className="builder-panel"><div className="builder-panel-head"><b>Saved routines</b><button type="button" className="builder-icon" onClick={()=>setShowTemplates(false)}><X size={16}/></button></div><div className="builder-save-template"><input aria-label="Routine name" placeholder="Name this routine" value={templateName} onChange={e=>setTemplateName(e.target.value)}/><button type="button" className="builder-button" disabled={!exercises.length||!templateName.trim()} onClick={()=>{setTemplates(old=>[...old,{name:templateName.trim(),exercises:exercises.map(x=>({...x}))}]);setTemplateName("");setMessage("Routine saved on this device.");}}>Save current</button></div>{templates.length===0?<p className="builder-note">Save a routine to reuse it later on this device.</p>:templates.map((t,i)=><div className="builder-template-row" key={t.name+i}><button type="button" onClick={()=>{setExercises(t.exercises.map(x=>({...x})));setSessionTitle(t.name);setDone([]);setSessionId(null);setShowTemplates(false);}}><b>{t.name}</b><small>{t.exercises.length} exercises</small></button><button className="builder-icon danger" type="button" onClick={()=>setTemplates(old=>old.filter((_,j)=>j!==i))}><X size={15}/></button></div>)}</section>}
 {showLibrary&&<section className="builder-panel"><div className="builder-panel-head"><div><b>Exercise library</b><small>Search by name or filter by muscle group</small></div><button type="button" className="builder-icon" onClick={()=>setShowLibrary(false)}><X size={16}/></button></div><input className="builder-search" placeholder="Search exercises…" value={search} onChange={e=>setSearch(e.target.value)}/><div className="builder-filters">{muscles.map(m=><button key={m} type="button" className={muscleFilter===m?"selected":""} onClick={()=>setMuscleFilter(m)}>{m}</button>)}</div><div className="builder-library-list">{filtered.map(x=><div className="builder-library-item" key={x.name}><span><b>{x.name}</b><small>{x.muscle} · {x.equipment}</small></span><button className="builder-icon add" type="button" aria-label={"Add "+x.name} onClick={()=>addExercise(x)}><Plus size={17}/></button></div>)}</div><div className="builder-custom"><b>Create custom exercise</b><div className="builder-custom-row"><input placeholder="Exercise name" value={customName} onChange={e=>setCustomName(e.target.value)}/><select value={customMuscle} onChange={e=>setCustomMuscle(e.target.value)}>{muscles.filter(x=>x!=="All").map(x=><option key={x}>{x}</option>)}</select></div><button className="builder-button secondary" type="button" disabled={!customName.trim()} onClick={()=>{const custom={name:customName.trim(),muscle:customMuscle,equipment:"Custom",kind:"weighted" as const,sets:"3",reps:"10",weight:""};setCustomLibrary(old=>old.some(x=>x.name.toLowerCase()===custom.name.toLowerCase())?old:[...old,custom]);addExercise(custom);setCustomName("");}}>Add custom exercise</button></div></section>}
 {exercises.length===0?<section className="builder-empty"><Dumbbell size={26}/><h3>Your workout starts here</h3><p>Add exercises from the library or generate a plan that matches your preferences.</p><button type="button" className="builder-button" onClick={()=>setShowLibrary(true)}><Plus size={15}/> Browse exercises</button></section>:<div className="builder-exercise-list">{exercises.map((x,i)=><article className="builder-exercise" key={x.name+i}><button type="button" className="builder-exercise-head" onClick={()=>setExpanded(expanded===i?null:i)}><span className="builder-exercise-number">{String(i+1).padStart(2,"0")}</span><span className="builder-exercise-title"><b>{x.name}</b><small>{x.muscle} · {x.equipment} · {x.sets} sets × {x.reps} {x.kind==="timed"?"sec":"reps"}</small></span><span className="builder-exercise-status">{done.includes(x.name)?<Check size={17}/>:null}<ChevronDown size={17} className={expanded===i?"rotated":""}/></span></button>{expanded===i&&<div className="builder-exercise-body"><div className="builder-edit-grid"><label>Sets<input type="number" min="1" max="10" value={x.sets} onChange={e=>updateExercise(i,"sets",e.target.value)}/></label><label>{x.kind==="timed"?"Seconds":"Reps per set"}<input type="number" min="1" max="1000" value={x.reps} onChange={e=>updateExercise(i,"reps",e.target.value)}/></label>{x.kind==="weighted"&&<label>Load (kg)<input type="number" min="0" step="0.25" placeholder="Optional" value={x.weight} onChange={e=>updateExercise(i,"weight",e.target.value)}/></label>}</div><div className="builder-exercise-actions"><button type="button" className="builder-button ghost" disabled={i===0} onClick={()=>setExercises(old=>{const next=[...old];[next[i-1],next[i]]=[next[i],next[i-1]];return next;})}>Move up</button><button type="button" className="builder-button ghost" disabled={i===exercises.length-1} onClick={()=>setExercises(old=>{const next=[...old];[next[i+1],next[i]]=[next[i],next[i+1]];return next;})}>Move down</button><button type="button" className="builder-button secondary" disabled={saving!==null} onClick={()=>void saveExercise(x)}>{saving===x.name?"Saving…":done.includes(x.name)?"Log another group":"Log exercise"} <Check size={14}/></button><button type="button" className="builder-button ghost" onClick={()=>removeExercise(i)}>Remove</button></div></div>}</article>)}</div>}
 {suggestionSource&&<p className="builder-note">{suggestionSource==="AI personalized"?"AI-generated from your selected preferences.":"Smart offline fallback — no AI provider is configured yet."} Your approval is required before training.</p>}
 {message&&<p className="food-form-message builder-message" role="status">{message}</p>}
 <section className="builder-history"><div className="builder-toolbar"><div><span className="eyebrow">YOUR TRAINING DATA</span><h3>Recent sessions</h3></div><button type="button" className="builder-icon" aria-label="Refresh workout history" onClick={()=>void loadHistory()}><Activity size={16}/></button></div>{historyLoading?<div className="builder-empty">Loading sessions…</div>:history.length===0?<div className="builder-empty">Your saved sessions will appear here after your first logged exercise.</div>:history.map(session=><article className="builder-history-card" key={session.id}><div className="builder-history-head"><div><b>{session.title||"Workout"}</b><small>{new Date(session.started_at).toLocaleString("en-PH",{dateStyle:"medium",timeStyle:"short"})} · {session.sets.length} sets</small></div><button className="builder-button danger" type="button" disabled={historyBusy!==null} onClick={()=>void deleteSession(session.id)}>Delete session</button></div>{session.sets.map(set=><div className="builder-history-set" key={set.id}>{editingSet===set.id?<><label>Reps<input type="number" value={editReps} onChange={e=>setEditReps(e.target.value)}/></label><label>Load (kg)<input type="number" value={editLoad} onChange={e=>setEditLoad(e.target.value)}/></label><button type="button" className="builder-button" disabled={historyBusy!==null} onClick={()=>void saveSet()}>Save</button></>:<><span>{set.exercise_name} · Set {set.set_number} · {set.reps} reps · {set.weight_kg===null?"No load":set.weight_kg+" kg"}</span><button type="button" className="builder-button secondary" onClick={()=>startEdit(set)}>Edit</button><button type="button" className="builder-button danger" disabled={historyBusy!==null} onClick={()=>void deleteSet(set.id)}>Delete</button></>}</div>)}</article>)}</section>
 </>;
}
function Nutrition(p:{protein:number;calories:number;water:number;carbs:number;fat:number;calorieGoal:number;proteinGoal:number;carbGoal:number;fatGoal:number;setCalorieGoal:(n:number)=>void;setProteinGoal:(n:number)=>void;setCarbGoal:(n:number)=>void;setFatGoal:(n:number)=>void;setWater:(n:number)=>void;setProtein:(fn:(v:number)=>number)=>void;setCalories:(fn:(v:number)=>number)=>void;setCarbs:(fn:(v:number)=>number)=>void;setFat:(fn:(v:number)=>number)=>void;entries:FoodEntry[];setEntries:(fn:(v:FoodEntry[])=>FoodEntry[])=>void;addLog:(l:string,a:number,u:string)=>void}){
 const [foodName,setFoodName]=useState("");
 const [mealType,setMealType]=useState("lunch");
 const [serving,setServing]=useState("1 serving");
 const [kcal,setKcal]=useState("");
 const [protein,setProteinInput]=useState("");
 const [carbs,setCarbsInput]=useState("");
 const [fat,setFatInput]=useState("");
 const [saving,setSaving]=useState(false);
 const [formMessage,setFormMessage]=useState("");
 const [editing,setEditing]=useState<string|null>(null);
 const [weekRows,setWeekRows]=useState<{day:string;date:string;calories:number;protein:number;carbs:number;fat:number;entries:number}[]>([]);
 const [weekLoading,setWeekLoading]=useState(true);const [,setFavorites]=useState<FoodEntry[]>([]);
 useEffect(()=>{try{const raw=localStorage.getItem("fitledger-favorite-meals");if(raw){const parsed=JSON.parse(raw);if(Array.isArray(parsed))setFavorites(parsed);}}catch{}},[]);
 useEffect(()=>{let active=true;(async()=>{try{const supabase=createClient();const {data:{user}}=await supabase.auth.getUser();if(!user){if(active)setWeekRows([]);return;}const from=new Date();from.setHours(0,0,0,0);from.setDate(from.getDate()-6);const {data,error}=await supabase.from("food_entries").select("logged_at,calories,protein_g,carbs_g,fat_g").eq("user_id",user.id).gte("logged_at",from.toISOString()).order("logged_at",{ascending:true});if(error)throw error;const days=new Map<string,{day:string;date:string;calories:number;protein:number;carbs:number;fat:number;entries:number}>();for(let offset=6;offset>=0;offset--){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-offset);const key=[d.getFullYear(),String(d.getMonth()+1).padStart(2,"0"),String(d.getDate()).padStart(2,"0")].join("-");days.set(key,{day:d.toLocaleDateString("en-PH",{weekday:"short"}),date:d.toLocaleDateString("en-PH",{month:"short",day:"numeric"}),calories:0,protein:0,carbs:0,fat:0,entries:0});}for(const row of data||[]){const d=new Date(row.logged_at);const key=[d.getFullYear(),String(d.getMonth()+1).padStart(2,"0"),String(d.getDate()).padStart(2,"0")].join("-");const item=days.get(key);if(item){item.calories+=Number(row.calories||0);item.protein+=Number(row.protein_g||0);item.carbs+=Number(row.carbs_g||0);item.fat+=Number(row.fat_g||0);item.entries++;}}if(active)setWeekRows(Array.from(days.values()));}catch(error){console.error("Nutrition history load failed",error);}finally{if(active)setWeekLoading(false);}})();return()=>{active=false;};},[]);

 const saveFavorite=(entry:FoodEntry)=>{setFavorites(old=>{const next=[entry,...old.filter(x=>x.food_name.toLowerCase()!==entry.food_name.toLowerCase())].slice(0,12);localStorage.setItem("fitledger-favorite-meals",JSON.stringify(next));return next;});setFormMessage(entry.food_name+" saved to quick meals.");};
 const deleteFood=async(entry:FoodEntry)=>{
  if(!window.confirm(`Delete "${entry.food_name}" from today's diary?`))return;
  setFormMessage("");
  try{
   const supabase=createClient();const {data:{user}}=await supabase.auth.getUser();
   if(!user){setFormMessage("Sign in to manage your food diary.");return;}
   const {error}=await supabase.from("food_entries").delete().eq("id",entry.id).eq("user_id",user.id);
   if(error)throw error;
   p.setEntries(v=>v.filter(x=>x.id!==entry.id));
   p.setCalories(v=>Math.max(0,v-Number(entry.calories)));
   p.setProtein(v=>Math.max(0,v-Number(entry.protein_g)));
   p.setCarbs(v=>Math.max(0,v-Number(entry.carbs_g)));
   p.setFat(v=>Math.max(0,v-Number(entry.fat_g)));
   if(editing===entry.id){setEditing(null);setFoodName("");setServing("1 serving");setKcal("");setProteinInput("");setCarbsInput("");setFatInput("");}
   setFormMessage("Food entry deleted.");
  }catch(error){console.error("Food delete failed",error);setFormMessage("Could not delete this entry. Please try again.");}
 };
 const submitFood=async(e:FormEvent<HTMLFormElement>)=>{
  e.preventDefault();setFormMessage("");
  const values=[kcal,protein||"0",carbs||"0",fat||"0"].map(Number);
  if(!foodName.trim()||!serving.trim()||!Number.isFinite(values[0])||values.some(v=>v<0)||values[0]>5000||values.slice(1).some(v=>v>500)){setFormMessage("Check the food name, serving and nutrition values.");return;}
  setSaving(true);
  try{
   if(editing){const supabase=createClient();const {data:{user}}=await supabase.auth.getUser();if(!user){setFormMessage("Sign in to update your diary.");return;}const current=p.entries.find(x=>x.id===editing);if(!current){setFormMessage("This entry is no longer available.");return;}const patch={food_name:foodName.trim(),serving_description:serving.trim(),meal_type:mealType,calories:values[0],protein_g:values[1],carbs_g:values[2],fat_g:values[3]};const {data:updated,error}=await supabase.from("food_entries").update(patch).eq("id",editing).eq("user_id",user.id).select("id,food_name,serving_description,meal_type,calories,protein_g,carbs_g,fat_g,logged_at").single();if(error||!updated){setFormMessage("Could not update this entry. Try again.");return;}p.setEntries(v=>v.map(x=>x.id===editing?updated as FoodEntry:x));p.setCalories(v=>Math.max(0,v-Number(current.calories)+values[0]));p.setProtein(v=>Math.max(0,v-Number(current.protein_g)+values[1]));p.setCarbs(v=>Math.max(0,v-Number(current.carbs_g)+values[2]));p.setFat(v=>Math.max(0,v-Number(current.fat_g)+values[3]));setEditing(null);setFoodName("");setServing("1 serving");setKcal("");setProteinInput("");setCarbsInput("");setFatInput("");setFormMessage("Food entry updated.");return;}

   const supabase=createClient();const {data:{user}}=await supabase.auth.getUser();
   if(!user){setFormMessage("Sign in to save food to your diary.");return;}
   const {data:savedFood,error}=await supabase.from("food_entries").insert({user_id:user.id,food_name:foodName.trim(),serving_description:serving.trim(),calories:values[0],protein_g:values[1],carbs_g:values[2],fat_g:values[3],meal_type:mealType}).select("id,food_name,serving_description,meal_type,calories,protein_g,carbs_g,fat_g,logged_at").single();
   if(error){setFormMessage("Could not save this entry. Please try again.");console.error("Food save failed",error);return;}
   if(savedFood)p.setEntries(v=>[savedFood as FoodEntry,...v]); p.setCalories(v=>v+values[0]);p.setProtein(v=>v+values[1]);p.setCarbs(v=>v+values[2]);p.setFat(v=>v+values[3]);
   p.addLog(foodName.trim(),values[0],"kcal");
   setFoodName("");setServing("1 serving");setKcal("");setProteinInput("");setCarbsInput("");setFatInput("");setFormMessage("Saved to your food diary.");
  }catch(error){console.error("Food save failed",error);setFormMessage("Something went wrong. Please try again.");}
  finally{setSaving(false);}
 };
 return <><Heading eyebrow="NUTRITION / DAILY INTAKE" title={<>Fuel your <em>day.</em></>} description="Log what you actually eat. Adjust portions and targets to fit your routine."/><div className="nutrition-hero"><div><div className="eyebrow">ENERGY LOGGED TODAY</div><div className="big-number">{p.calories.toLocaleString()} <small>kcal</small></div><span className="muted">Only entries you add are counted here</span><div className="wide-track"><span style={{width:(p.calorieGoal>0?Math.min(100,p.calories/p.calorieGoal*100):0)+"%"}}/></div><small className="nutrition-guide-note">Set an optional target below; no calorie target is assumed.</small></div><div className="macro-rings"><Ring value={p.proteinGoal>0?Math.min(100,Math.round(p.protein/p.proteinGoal*100)):0} label="Protein" sub={p.protein+" g logged"}/><Ring value={p.carbGoal>0?Math.min(100,Math.round(p.carbs/p.carbGoal*100)):0} label="Carbs" sub={p.carbs+" g logged"} color="blue"/><Ring value={p.fatGoal>0?Math.min(100,Math.round(p.fat/p.fatGoal*100)):0} label="Fat" sub={p.fat+" g logged"} color="orange"/></div></div>
 <details className="nutrition-targets"><summary>Personalize your daily targets <span>Optional · editable anytime</span></summary><div className="nutrition-target-grid"><label>Calories (kcal)<input type="number" min="0" max="10000" value={p.calorieGoal||""} placeholder="Not set" onChange={e=>p.setCalorieGoal(Math.max(0,Number(e.target.value)||0))}/></label><label>Protein (g)<input type="number" min="0" max="1000" value={p.proteinGoal||""} placeholder="Not set" onChange={e=>p.setProteinGoal(Math.max(0,Number(e.target.value)||0))}/></label><label>Carbs (g)<input type="number" min="0" max="1500" value={p.carbGoal||""} placeholder="Not set" onChange={e=>p.setCarbGoal(Math.max(0,Number(e.target.value)||0))}/></label><label>Fat (g)<input type="number" min="0" max="1000" value={p.fatGoal||""} placeholder="Not set" onChange={e=>p.setFatGoal(Math.max(0,Number(e.target.value)||0))}/></label></div><p>Targets are your own tracking preferences, not medical recommendations. Leave a field blank to track intake without a target.</p></details><div className="section-heading"><div><div className="eyebrow">LAST 7 DAYS</div><h3>Nutrition history</h3></div><span className="subtle-label">SAVED ENTRIES</span></div>{weekLoading?<div className="panel-card empty-state">Loading your weekly nutrition…</div>:<div className="panel-card metric-history">{weekRows.map(row=><div className="activity-row" key={row.date}><span className="activity-mark"><CalendarDays size={14}/></span><span><b>{row.day} · {row.date}</b><small>{row.entries} food entries · {Math.round(row.protein)} g protein</small></span><strong>{Math.round(row.calories).toLocaleString()} kcal</strong></div>)}<p className="nutrition-guide-note">Only meals saved in your diary are included. Blank days mean no entries were recorded, not zero food intake.</p></div>}<div className="section-heading"><div><div className="eyebrow">YOUR FOOD DIARY</div><h3>Today’s entries</h3></div><span className="subtle-label">{p.entries.length} LOGGED</span></div>{p.entries.length===0?<div className="panel-card empty-state"><b>No meals logged today</b><span>Add your first meal below. Your totals will update from saved entries.</span></div>:<div className="panel-card food-history-list">{p.entries.map(entry=><div className="activity-row" key={entry.id}><span className="activity-mark"><Utensils size={14}/></span><span><b>{entry.food_name}</b><small>{entry.meal_type} · {entry.serving_description}</small></span><strong>{Number(entry.calories).toLocaleString()} kcal</strong><button type="button" className="icon-btn" aria-label={"Save "+entry.food_name+" as quick meal"} onClick={()=>saveFavorite(entry)}><Zap size={14}/></button><button type="button" className="icon-btn" aria-label={"Edit "+entry.food_name} onClick={()=>{setEditing(entry.id);setFoodName(entry.food_name);setServing(entry.serving_description);setMealType(entry.meal_type);setKcal(String(entry.calories));setProteinInput(String(entry.protein_g));setCarbsInput(String(entry.carbs_g));setFatInput(String(entry.fat_g));setFormMessage("Editing "+entry.food_name);}}><Settings2 size={14}/></button><button type="button" className="icon-btn" aria-label={"Delete "+entry.food_name} onClick={()=>void deleteFood(entry)}><X size={14}/></button></div>)}</div>}<div className="section-heading"><div><div className="eyebrow">{editing?"EDIT FOOD ENTRY":"ADD A MEAL"}</div><h3>{editing?"Update your entry":"Log what you ate"}</h3></div></div>
 <form className="food-entry-form" onSubmit={submitFood}>
  <label>Food or meal<input value={foodName} onChange={e=>setFoodName(e.target.value)} placeholder="e.g. Chicken adobo" required maxLength={100}/></label>
  <div className="food-form-grid"><label>Meal<select value={mealType} onChange={e=>setMealType(e.target.value)}><option value="breakfast">Breakfast</option><option value="lunch">Lunch</option><option value="dinner">Dinner</option><option value="snack">Snack</option></select></label><label>Serving<input value={serving} onChange={e=>setServing(e.target.value)} placeholder="e.g. 100 g" required maxLength={60}/></label></div>
  <div className="food-form-grid four"><label>Calories (kcal)<input type="number" min="0" max="5000" step="1" inputMode="numeric" value={kcal} onChange={e=>setKcal(e.target.value)} placeholder="Required" required/></label><label>Protein (g)<input type="number" min="0" max="500" step="0.1" inputMode="decimal" value={protein} onChange={e=>setProteinInput(e.target.value)} placeholder="0"/></label><label>Carbs (g)<input type="number" min="0" max="500" step="0.1" inputMode="decimal" value={carbs} onChange={e=>setCarbsInput(e.target.value)} placeholder="0"/></label><label>Fat (g)<input type="number" min="0" max="500" step="0.1" inputMode="decimal" value={fat} onChange={e=>setFatInput(e.target.value)} placeholder="0"/></label></div>
  {formMessage&&<p className="food-form-message" role="status">{formMessage}</p>}
  <button className="food-save-btn" type="submit" disabled={saving}>{saving?"Saving…":editing?"Update entry":"Add to diary"} <Plus size={16}/></button>
 </form>
 <div className="meal-media-card"><div className="meal-media-image" role="img" aria-label="Filipino-style chicken adobo, tofu, egg and rice meal"/><div className="meal-media-copy"><div className="eyebrow">MEAL INSPIRATION · OPTIONAL</div><h3>Filipino meals that fit a student budget</h3><p>Explore practical meal ideas. Portions, prices and nutrition vary—use your own serving details when logging.</p><div className="meal-media-links"><a href="https://www.youtube.com/watch?v=2QM9Q8EPYTI" target="_blank" rel="noreferrer">Watch budget Filipino recipes <ArrowRight size={14}/></a><a href="https://www.pexels.com/photo/healthy-meal-prep-with-rice-and-vegetables-30635714/" target="_blank" rel="noreferrer">Browse free meal-prep photography on Pexels</a></div></div></div>
 <div className="section-heading"><div><div className="eyebrow">HYDRATION</div><h3>Water check-in</h3></div><span className="subtle-label">{p.water} OF 8 GLASSES</span></div><div className="water-card"><div className="water-glasses">{Array.from({length:8},(_,i)=><button key={i} onClick={()=>p.setWater(i+1)} className={i<p.water?"glass filled-glass":"glass"} aria-label={`Set water to ${i+1} glasses`}><span/></button>)}</div><span>Tap a glass to update your water intake</span></div></>;
}
function Ring(p:{value:number;label:string;sub:string;color?:string}){return <div className="ring-wrap"><div className={`ring ${p.color||""}`} style={{"--progress":p.value+"%"} as React.CSSProperties}><div className="ring-inner"><strong>{p.value}%</strong></div></div><div><b>{p.label}</b><span>{p.sub}</span></div></div>;}
function Budget(p:{spent:number;entries:BudgetEntry[];setEntries:(fn:(v:BudgetEntry[])=>BudgetEntry[])=>void;setSpent:(fn:(v:number)=>number)=>void}){
 const [description,setDescription]=useState("");const [category,setCategory]=useState("Food");const [amount,setAmount]=useState("");const [saving,setSaving]=useState(false);const [message,setMessage]=useState("");
 const save=async(e:FormEvent)=>{e.preventDefault();const n=Number(amount);if(!Number.isFinite(n)||n<=0||n>100000){setMessage("Enter an amount above ₱0 and below ₱100,000.");return;}setSaving(true);setMessage("");try{const supabase=createClient();const {data:{user}}=await supabase.auth.getUser();if(!user){setMessage("Please sign in again.");return;}const now=new Date();const entryDate=[now.getFullYear(),String(now.getMonth()+1).padStart(2,"0"),String(now.getDate()).padStart(2,"0")].join("-");const {data,error}=await supabase.from("budget_entries").insert({user_id:user.id,entry_date:entryDate,category,description:description.trim()||category,amount:n,entry_type:"expense"}).select("id,entry_date,category,description,amount,entry_type").single();if(error||!data){setMessage("Could not save this expense. Try again.");return;}p.setEntries(v=>[data as BudgetEntry,...v]);p.setSpent(v=>v+n);setAmount("");setDescription("");setMessage("Expense saved.");}catch(error){console.error("Budget save failed",error);setMessage("Something went wrong. Please check your connection and try again.");}finally{setSaving(false);}};
 const remove=async(entry:BudgetEntry)=>{
  if(!window.confirm(`Delete "${entry.description}" from today's spending log?`))return;
  setMessage("");
  try{
   const supabase=createClient();const {data:{user}}=await supabase.auth.getUser();
   if(!user){setMessage("Please sign in again.");return;}
   const {error}=await supabase.from("budget_entries").delete().eq("id",entry.id).eq("user_id",user.id);
   if(error)throw error;
   p.setEntries(v=>v.filter(x=>x.id!==entry.id));
   if(entry.entry_type==="expense")p.setSpent(v=>Math.max(0,v-Number(entry.amount)));
   setMessage("Expense deleted.");
  }catch(error){console.error("Budget delete failed",error);setMessage("Could not delete this entry. Try again.");}
 };
 return <><Heading eyebrow="BUDGET / FOOD ALLOWANCE" title={<>Make every peso <em>count.</em></>} description="Record your actual spending. Set your own daily guide when you need one."/><div className="budget-hero"><div className="eyebrow">TODAY&apos;S RECORDED EXPENSES</div><div className="budget-amount">{money(p.spent)} <small>spent today</small></div><div className="budget-labels"><span>{p.entries.length} saved entries</span><span>Personal records</span></div></div><div className="section-heading"><div><div className="eyebrow">ADD AN EXPENSE</div><h3>Record a purchase</h3></div></div><form className="food-entry-form" onSubmit={save}><label>Description<input value={description} onChange={e=>setDescription(e.target.value)} placeholder="e.g. Lunch at canteen" maxLength={100}/></label><div className="food-form-grid"><label>Category<select value={category} onChange={e=>setCategory(e.target.value)}><option>Food</option><option>Groceries</option><option>Transport</option><option>Fitness</option><option>Other</option></select></label><label>Amount (₱)<input type="number" min="0.01" max="100000" step="0.01" inputMode="decimal" required value={amount} onChange={e=>setAmount(e.target.value)} placeholder="0.00"/></label></div>{message&&<p className="food-form-message" role="status">{message}</p>}<button className="food-save-btn" disabled={saving}>{saving?"Saving…":"Save expense"} <Plus size={15}/></button></form><div className="section-heading"><div><div className="eyebrow">TODAY&apos;S SPENDING LOG</div><h3>Saved transactions</h3></div><span className="subtle-label">{p.entries.length} ENTRIES</span></div>{p.entries.length===0?<div className="panel-card empty-state"><b>No expenses recorded today</b><span>Add a purchase above. Only saved transactions appear here.</span></div>:<div className="panel-card budget-history">{p.entries.map(entry=><div className="activity-row" key={entry.id}><span className="activity-mark"><Wallet size={14}/></span><span><b>{entry.description}</b><small>{entry.category} · {entry.entry_date}</small></span><strong>{money(Number(entry.amount))}</strong><button type="button" className="icon-btn" aria-label={"Delete "+entry.description} onClick={()=>void remove(entry)}><X size={14}/></button></div>)}</div>}<div className="panel-card budget-tip"><div className="tip-icon"><Sparkles size={18}/></div><div><b>Affordable protein ideas</b><p>Eggs, monggo, tokwa, canned sardines and chicken portions are useful options to compare at your local market. Prices vary by store and season.</p></div></div></>;
}
function Progress(p:{weight:string;onSave:(v:string,waist?:number)=>Promise<boolean>;history:BodyMetric[];xp:number}){
 const [draft,setDraft]=useState(p.weight);const [waistDraft,setWaistDraft]=useState("");const [photos,setPhotos]=useState<{id:string;date:string;src:string}[]>([]);const [photoMessage,setPhotoMessage]=useState("");const [saving,setSaving]=useState(false);const [message,setMessage]=useState("");
 const [workouts,setWorkouts]=useState<{id:string;title:string|null;started_at:string}[]>([]);
 const [strengthRows,setStrengthRows]=useState<{exercise_name:string;weight_kg:number|null;reps:number;completed_at:string;session_id:string}[]>([]);
 const [activityLoading,setActivityLoading]=useState(true);const [activityError,setActivityError]=useState("");
 const [selectedExercise,setSelectedExercise]=useState("");const [nutritionWeek,setNutritionWeek]=useState<{calories:number;protein:number;loggedDays:number;entries:number}>({calories:0,protein:0,loggedDays:0,entries:0});
 useEffect(()=>setDraft(p.weight),[p.weight]);useEffect(()=>{try{const raw=localStorage.getItem("fitledger-progress-photos");if(raw){const parsed=JSON.parse(raw);if(Array.isArray(parsed))setPhotos(parsed);}}catch{}},[]);
 useEffect(()=>{let active=true;(async()=>{setActivityLoading(true);setActivityError("");try{const supabase=createClient();const {data:{user}}=await supabase.auth.getUser();if(!user){if(active){setWorkouts([]);setStrengthRows([]);}return;}const since=new Date();since.setDate(since.getDate()-29);since.setHours(0,0,0,0);const {data:sessions,error}=await supabase.from("workout_sessions").select("id,title,started_at").eq("user_id",user.id).gte("started_at",since.toISOString()).order("started_at",{ascending:true});if(error)throw error;const weekStart=new Date();weekStart.setHours(0,0,0,0);weekStart.setDate(weekStart.getDate()-6);const {data:foods,error:foodError}=await supabase.from("food_entries").select("logged_at,calories,protein_g").eq("user_id",user.id).gte("logged_at",weekStart.toISOString());if(foodError)throw foodError;const loggedDates=new Set((foods||[]).map(x=>new Date(x.logged_at).toLocaleDateString("en-CA")));const foodCount=(foods||[]).length;const caloriesTotal=(foods||[]).reduce((sum,x)=>sum+Number(x.calories||0),0);const proteinTotal=(foods||[]).reduce((sum,x)=>sum+Number(x.protein_g||0),0);const ids=(sessions||[]).map(x=>x.id);let rows:{exercise_name:string;weight_kg:number|null;reps:number;completed_at:string;session_id:string}[]=[];if(ids.length){const result=await supabase.from("workout_sets").select("exercise_name,weight_kg,reps,completed_at,session_id").eq("user_id",user.id).in("session_id",ids).not("weight_kg","is",null).order("completed_at",{ascending:true});if(result.error)throw result.error;rows=(result.data||[]).filter(x=>x.weight_kg!==null) as typeof rows;}if(active){setWorkouts(sessions||[]);setStrengthRows(rows);setNutritionWeek({calories:loggedDates.size?caloriesTotal/loggedDates.size:0,protein:loggedDates.size?proteinTotal/loggedDates.size:0,loggedDays:loggedDates.size,entries:foodCount});const first=Array.from(new Set(rows.map(x=>x.exercise_name)))[0]||"";setSelectedExercise(current=>current||first);}}catch(error){console.error("Progress activity load failed",error);if(active)setActivityError("Workout trends could not be loaded. Check your connection and refresh.");}finally{if(active)setActivityLoading(false);}})();return()=>{active=false;};},[]);
 const save=async()=>{const value=Number(draft);const waist=waistDraft.trim()===""?undefined:Number(waistDraft);if(!Number.isFinite(value)||value<1||value>500){setMessage("Enter a weight between 1 and 500 kg.");return;}if(waist!==undefined&&(!Number.isFinite(waist)||waist<30||waist>250)){setMessage("Enter a waist measurement between 30 and 250 cm.");return;}setSaving(true);setMessage("");try{const saved=await p.onSave(value.toFixed(1),waist);if(!saved){setMessage("Your check-in could not be saved. Please try again.");return;}if(waist!==undefined)setWaistDraft("");setMessage(waist===undefined?"Weight check-in saved.":"Weight and waist check-ins saved.");}catch(error){console.error("Body check-in failed",error);setMessage("Could not save this check-in. Please try again.");}finally{setSaving(false);}};
 const addProgressPhoto=(file:File)=>{if(!file.type.startsWith("image/")){setPhotoMessage("Choose an image file.");return;}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const canvas=document.createElement("canvas");const scale=Math.min(1,720/Math.max(img.width,img.height));canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);const ctx=canvas.getContext("2d");if(!ctx){setPhotoMessage("Could not process this image.");return;}ctx.drawImage(img,0,0,canvas.width,canvas.height);const src=canvas.toDataURL("image/jpeg",0.72);setPhotos(old=>{const next=[{id:crypto.randomUUID(),date:new Date().toISOString(),src},...old].slice(0,6);try{localStorage.setItem("fitledger-progress-photos",JSON.stringify(next));setPhotoMessage("Progress photo saved on this device.");return next;}catch{setPhotoMessage("Device storage is full. Delete an older photo and try again.");return old;}});};img.onerror=()=>setPhotoMessage("Could not read this image.");img.src=String(reader.result);};reader.onerror=()=>setPhotoMessage("Could not read this image.");reader.readAsDataURL(file);};
 const waistPoints=p.history.filter(x=>x.waist_cm!==null&&x.waist_cm!==undefined).slice().sort((a,b)=>new Date(a.measured_at).getTime()-new Date(b.measured_at).getTime());
 const weeklyCompare=(key:"weight_kg"|"waist_cm")=>{const source=p.history.filter(x=>x[key]!==null&&x[key]!==undefined);const now=Date.now();const recent=source.filter(x=>now-new Date(x.measured_at).getTime()<=7*86400000);const previous=source.filter(x=>{const age=now-new Date(x.measured_at).getTime();return age>7*86400000&&age<=14*86400000;});const avg=(rows:BodyMetric[])=>rows.length?rows.reduce((sum,x)=>sum+Number(x[key]||0),0)/rows.length:null;return {current:avg(recent),previous:avg(previous),count:recent.length};};
 const weightComparison=weeklyCompare("weight_kg");const waistComparison=weeklyCompare("waist_cm");
 const comparisonLabel=(current:number|null,previous:number|null,unit:string)=>current===null?"No check-ins this week":previous===null?"No previous-week data":`${current-previous>0?"↑":current-previous<0?"↓":"→"} ${Math.abs(current-previous).toFixed(1)} ${unit} vs previous 7 days`;
 const weightPoints=p.history.filter(x=>x.weight_kg!==null).slice().sort((a,b)=>new Date(a.measured_at).getTime()-new Date(b.measured_at).getTime()).map(x=>({date:new Date(x.measured_at).toLocaleDateString("en-PH",{month:"short",day:"numeric"}),weight:Number(x.weight_kg)}));
 const dayMap=new Map<string,{date:string;workouts:number}>();for(let offset=29;offset>=0;offset--){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-offset);const key=[d.getFullYear(),String(d.getMonth()+1).padStart(2,"0"),String(d.getDate()).padStart(2,"0")].join("-");dayMap.set(key,{date:d.toLocaleDateString("en-PH",{month:"short",day:"numeric"}),workouts:0});}
 for(const session of workouts){const d=new Date(session.started_at);const key=[d.getFullYear(),String(d.getMonth()+1).padStart(2,"0"),String(d.getDate()).padStart(2,"0")].join("-");const point=dayMap.get(key);if(point)point.workouts+=1;}
 const workoutPoints=Array.from(dayMap.values());
 const sevenDaysAgo=new Date();sevenDaysAgo.setHours(0,0,0,0);sevenDaysAgo.setDate(sevenDaysAgo.getDate()-6);const weekSessions=workouts.filter(x=>new Date(x.started_at)>=sevenDaysAgo).length;const weekSets=strengthRows.filter(x=>new Date(x.completed_at)>=sevenDaysAgo);const weeklyVolume=weekSets.reduce((sum,x)=>sum+Number(x.weight_kg||0)*Number(x.reps||0),0);const consistency=Math.min(100,Math.round(weekSessions/3*100)); const exercises=Array.from(new Set(strengthRows.map(x=>x.exercise_name))).sort();
 const strengthPoints=strengthRows.filter(x=>x.exercise_name===selectedExercise).reduce((acc,row)=>{const date=new Date(row.completed_at).toLocaleDateString("en-PH",{month:"short",day:"numeric"});const existing=acc.find(x=>x.date===date);if(existing){existing.load=Math.max(existing.load,Number(row.weight_kg));existing.reps=Math.max(existing.reps,Number(row.reps));}else acc.push({date,load:Number(row.weight_kg),reps:Number(row.reps)});return acc;},[] as {date:string;load:number;reps:number}[]);
 return <><Heading eyebrow="PROGRESS / BODY & HABITS" title={<>Progress, not <em>pressure.</em></>} description="Look for the trend, not a perfect day."/><RankCard xp={p.xp}/><div className="section-heading"><div><div className="eyebrow">YOUR LAST 7 DAYS</div><h3>Weekly fitness snapshot</h3></div><span className="subtle-label">SAVED DATA ONLY</span></div><div className="fitness-snapshot"><div className="panel-card snapshot-card"><div className="eyebrow">AVG CALORIES</div><strong>{nutritionWeek.loggedDays?Math.round(nutritionWeek.calories).toLocaleString():"—"}</strong><small>kcal per logged day</small></div><div className="panel-card snapshot-card"><div className="eyebrow">AVG PROTEIN</div><strong>{nutritionWeek.loggedDays?Math.round(nutritionWeek.protein):"—"}</strong><small>grams per logged day</small></div><div className="panel-card snapshot-card"><div className="eyebrow">WORKOUT CONSISTENCY</div><strong>{weekSessions}/3</strong><small>sessions · {consistency}% of 3-session reference</small><div className="wide-track"><span style={{width:consistency+"%"}}/></div></div><div className="panel-card snapshot-card"><div className="eyebrow">LOADED VOLUME</div><strong>{weeklyVolume>=1000?(weeklyVolume/1000).toFixed(1)+"k":Math.round(weeklyVolume).toLocaleString()}</strong><small>kg × reps · loaded sets only</small></div></div><p className="nutrition-guide-note">Nutrition averages use days with at least one saved food entry. The three-session reference is a simple tracking benchmark, not a medical or coaching assessment. Loaded volume excludes bodyweight and unweighted sets.</p><div className="progress-summary"><div className="panel-card"><div className="eyebrow">LATEST BODY WEIGHT</div><div className="weight-number">{p.weight}<small> kg</small></div><span className="muted">Your latest saved check-in</span><label className="weight-input-label">New check-in (kg)<input type="number" min="1" max="500" step="0.1" inputMode="decimal" aria-label="Weight in kilograms" value={draft} onChange={e=>setDraft(e.target.value)}/></label><button className="food-save-btn progress-save-btn" type="button" onClick={()=>void save()} disabled={saving}>{saving?"Saving…":"Save check-in"} <Check size={15}/></button>{message&&<p className="food-form-message" role="status">{message}</p>}</div><div className="panel-card"><div className="eyebrow">YOUR APPROACH</div><h3>Body recomposition</h3><p className="muted">Build strength while gradually improving body composition. Keep training consistent, eat enough, and track changes over time.</p><div className="goal-tag"><Target size={15}/> Strength + sustainable habits</div></div><div className="panel-card"><div className="eyebrow">WAIST MEASUREMENT</div><div className="weight-number">{waistPoints.length?Number(waistPoints[waistPoints.length-1].waist_cm).toFixed(1):"—"}<small> cm</small></div><span className="muted">Latest recorded waist check-in</span><label className="weight-input-label">New waist check-in (cm)<input type="number" min="30" max="250" step="0.1" inputMode="decimal" value={waistDraft} onChange={e=>setWaistDraft(e.target.value)} placeholder="Optional"/></label></div></div>
 <div className="section-heading"><div><div className="eyebrow">BODY WEIGHT · ACTUAL CHECK-INS</div><h3>Weight trend</h3></div><span className="subtle-label">{weightPoints.length} MEASUREMENTS</span></div>{weightPoints.length<2?<div className="panel-card empty-state"><b>{weightPoints.length===0?"No weight trend yet":"One more check-in to show a trend"}</b><span>Only your saved measurements appear here. Add another check-in on a different day to see the line.</span></div>:<div className="panel-card progress-chart"><div className="chart-caption">Recorded weight · kilograms</div><div style={{width:"100%",height:230}}><ResponsiveContainer width="100%" height="100%"><LineChart data={weightPoints} margin={{top:12,right:12,left:-18,bottom:4}}><CartesianGrid stroke="#343d2e" strokeDasharray="3 3"/><XAxis dataKey="date" tick={{fill:"#aab29f",fontSize:10}} axisLine={false} tickLine={false}/><YAxis domain={["auto","auto"]} tick={{fill:"#aab29f",fontSize:10}} axisLine={false} tickLine={false} width={42}/><Tooltip contentStyle={{background:"#20251e",border:"1px solid #46513b",borderRadius:8,color:"#f1f4eb"}} formatter={(value)=>[Number(value).toFixed(1)+" kg","Weight"]}/><Line type="monotone" dataKey="weight" stroke="#b9ee5c" strokeWidth={2.5} dot={{r:3,fill:"#b9ee5c",stroke:"#1b2118",strokeWidth:2}} activeDot={{r:5}}/></LineChart></ResponsiveContainer></div></div>}
 <div className="section-heading"><div><div className="eyebrow">WEEKLY BODY CHECK</div><h3>Recent comparison</h3></div><span className="subtle-label">ACTUAL RECORDS</span></div><div className="progress-summary"><div className="panel-card"><b>Weight · last 7 days</b><div className="weight-number">{weightComparison.current===null?"—":weightComparison.current.toFixed(1)}<small> kg avg</small></div><span className="muted">{weightComparison.count} check-ins · {comparisonLabel(weightComparison.current,weightComparison.previous,"kg")}</span></div><div className="panel-card"><b>Waist · last 7 days</b><div className="weight-number">{waistComparison.current===null?"—":waistComparison.current.toFixed(1)}<small> cm avg</small></div><span className="muted">{waistComparison.count} check-ins · {comparisonLabel(waistComparison.current,waistComparison.previous,"cm")}</span></div></div>
 <div className="section-heading"><div><div className="eyebrow">PROGRESS PHOTOS</div><h3>Visual check-ins</h3></div><span className="subtle-label">PRIVATE · THIS DEVICE</span></div><div className="panel-card progress-photos"><label className="food-save-btn photo-upload">Add progress photo <input type="file" accept="image/*" capture="environment" onChange={e=>{const file=e.target.files?.[0];if(file)addProgressPhoto(file);e.currentTarget.value="";}}/></label><p className="nutrition-guide-note">Photos are resized and saved only in this browser on this device. They are not uploaded to Supabase. Keep photos private and use consistent lighting and conditions.</p>{photoMessage&&<p className="food-form-message" role="status">{photoMessage}</p>}{photos.length===0?<div className="empty-state compact-empty">No progress photos saved yet.</div>:<div className="progress-photo-grid">{photos.map(photo=><div className="progress-photo-item" key={photo.id}><img src={photo.src} alt={"Progress photo from "+new Date(photo.date).toLocaleDateString("en-PH")}/><div><small>{new Date(photo.date).toLocaleDateString("en-PH",{month:"short",day:"numeric",year:"numeric"})}</small><button type="button" className="icon-btn" aria-label="Delete progress photo" onClick={()=>{if(!window.confirm("Delete this progress photo from this device?"))return;setPhotos(old=>{const next=old.filter(x=>x.id!==photo.id);localStorage.setItem("fitledger-progress-photos",JSON.stringify(next));return next;});}}><X size={14}/></button></div></div>)}</div>}</div>
 <div className="section-heading"><div><div className="eyebrow">TRAINING · LAST 30 DAYS</div><h3>Workout consistency</h3></div><span className="subtle-label">{workouts.length} SESSIONS</span></div>{activityLoading?<div className="panel-card empty-state">Loading workout activity…</div>:activityError?<div className="panel-card empty-state">{activityError}</div>:workouts.length===0?<div className="panel-card empty-state"><b>No saved workouts in this period</b><span>When you save workout sessions, your daily training frequency will appear here.</span></div>:<div className="panel-card progress-chart"><div className="chart-caption">Saved workout sessions per day · not individual exercises</div><div style={{width:"100%",height:220}}><ResponsiveContainer width="100%" height="100%"><BarChart data={workoutPoints} margin={{top:12,right:8,left:-18,bottom:4}}><CartesianGrid stroke="#343d2e" strokeDasharray="3 3"/><XAxis dataKey="date" interval={4} tick={{fill:"#aab29f",fontSize:10}} axisLine={false} tickLine={false}/><YAxis allowDecimals={false} tick={{fill:"#aab29f",fontSize:10}} axisLine={false} tickLine={false} width={32}/><Tooltip contentStyle={{background:"#20251e",border:"1px solid #46513b",borderRadius:8,color:"#f1f4eb"}} formatter={(value)=>[value+" session(s)","Workouts"]}/><Bar dataKey="workouts" fill="#b9ee5c" radius={[4,4,0,0]}/></BarChart></ResponsiveContainer></div></div>}
 <div className="section-heading"><div><div className="eyebrow">RECORDED LOADS · LAST 30 DAYS</div><h3>Strength progression</h3></div><span className="subtle-label">{strengthRows.length} LOADED SETS</span></div>{activityLoading?<div className="panel-card empty-state">Loading recorded strength…</div>:exercises.length===0?<div className="panel-card empty-state"><b>No loaded sets recorded yet</b><span>Enter a load in kilograms when saving a workout. Bodyweight or blank-load sets are not estimated or plotted.</span></div>:<div className="panel-card progress-chart"><label className="strength-select-label">Exercise<select value={selectedExercise} onChange={e=>setSelectedExercise(e.target.value)}>{exercises.map(name=><option key={name} value={name}>{name}</option>)}</select></label>{strengthPoints.length<2?<div className="empty-state compact-empty"><b>More sessions needed</b><span>Save the same exercise with a recorded load on another date to compare strength over time.</span>{strengthPoints.length===1&&<strong>{strengthPoints[0].load.toFixed(1)} kg · {strengthPoints[0].date}</strong>}</div>:<><div className="chart-caption">Highest recorded set load per day · kilograms</div><div style={{width:"100%",height:220}}><ResponsiveContainer width="100%" height="100%"><LineChart data={strengthPoints} margin={{top:12,right:12,left:-18,bottom:4}}><CartesianGrid stroke="#343d2e" strokeDasharray="3 3"/><XAxis dataKey="date" tick={{fill:"#aab29f",fontSize:10}} axisLine={false} tickLine={false}/><YAxis domain={["auto","auto"]} tick={{fill:"#aab29f",fontSize:10}} axisLine={false} tickLine={false} width={42}/><Tooltip contentStyle={{background:"#20251e",border:"1px solid #46513b",borderRadius:8,color:"#f1f4eb"}} formatter={(value)=>[Number(value).toFixed(1)+" kg","Load"]}/><Line type="monotone" dataKey="load" stroke="#7fc9ff" strokeWidth={2.5} dot={{r:3,fill:"#7fc9ff",stroke:"#1b2118",strokeWidth:2}}/></LineChart></ResponsiveContainer></div></>}</div>}
 <div className="section-heading"><div><div className="eyebrow">WEIGHT HISTORY</div><h3>Your saved check-ins</h3></div><span className="subtle-label">{p.history.length} RECORDS</span></div>{p.history.length===0?<div className="panel-card empty-state"><b>No check-ins yet</b><span>Save your first measurement above. Trends will appear as you add records.</span></div>:<div className="panel-card metric-history">{p.history.slice(0,12).map(item=><div className="activity-row" key={item.id}><span className="activity-mark"><TrendingUp size={14}/></span><span><b>{new Date(item.measured_at).toLocaleDateString("en-PH",{month:"short",day:"numeric",year:"numeric"})}</b><small>{new Date(item.measured_at).toLocaleTimeString("en-PH",{hour:"numeric",minute:"2-digit"})}</small></span><strong>{item.weight_kg===null?"—":item.weight_kg.toFixed(1)+" kg"}</strong></div>)}</div>}<div className="panel-card progress-reminder"><Activity size={19}/><div><b>One data point at a time</b><p>Weight can fluctuate from day to day. Consider waist, strength, sleep and how you feel too. A single weigh-in never tells the whole story. Charts show only measurements and workout loads you actually saved; no estimated values are added.</p></div></div></>;
}
